import math

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def simplify_sqrt(n):
    factors = prime_factors(n)
    unique_factors = set(factors)
    count = {}
    for factor in unique_factors:
        count[factor] = factors.count(factor)
    pairs = {}
    for factor, freq in count.items():
        pairs[factor] = freq // 2
    outside_sqrt = 1
    inside_sqrt = 1
    for factor, freq in pairs.items():
        inside_sqrt *= (factor ** freq)
    for factor, freq in count.items():
        if freq % 2 != 0:
            outside_sqrt *= factor
    return f"{outside_sqrt}*sqrt({inside_sqrt})"

