Thought: To simplify $\sqrt{242}$, I need to check if 242 is a perfect square by finding its square root and checking if it's an integer. If it's not a perfect square, I will find its prime factorization to identify perfect square factors. Then, I will use the prime factorization to simplify the squ ...[cut]... ctorization of 242
def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

factors_of_242 = prime_factors(242)
print(factors_of_242)

# Simplify the square root
perfect_square_factors = set()
for factor in factors_of_242:
    if factors_of_242.count(factor) % 2 == 0:
        perfect_square_factors.add(factor ** 2)

simplified_sqrt_242 = 1
for factor in perfect_square_factors:
    simplified_sqrt_242 *= factor ** (factors_of_242.count(factor) // 2)

remaining_factors = [factor for factor in factors_of_242 if factor not in perfect_square_factors]
remaining_sqrt_242 = 1
for factor in remaining_factors:
    remaining_sqrt_242 *= factor

print("Simplified sqrt(242) =", simplified_sqrt_242, "*", remaining_sqrt_242)
