import sympy

def sum_of_divisors(n):
    """Compute the sum of the divisors of n"""
    divisors = [i for i in range(1, n + 1) if n % i == 0]
    return sum(divisors)

def distinct_prime_divisors(n):
    """Compute the sum of the distinct prime divisors of n"""
    prime_divisors = set()
    for i in range(2, int(n**0.5) + 1):
        while n % i == 0:
            prime_divisors.add(i)
            n //= i
    if n > 1:
        prime_divisors.add(n)
    return sum(prime_divisors)

def main():
    n = 500
    A = sum_of_divisors(n)
    distinct_sum = distinct_prime_divisors(A)
    print(distinct_sum)

if __name__ == "__main__":
    main()
```

